// === Tab: mySketch ===
let p = [];
function setup() {


	createCanvas(windowWidth, windowHeight);
	textSize(width/30);
	colorMode(HSB,100);
	textAlign(CENTER);
}

function draw() {

	if(frameCount%20 == 0 && frameCount > 100 && p.length < 50){
		p.push(new Particle(random(width),random(height)));
		p.push(new Particle(random(width),random(height)));
	}
	  background(0);
	if(p.length < 1){
		fill(100);
		noStroke();
		text("Draw with your mouse",width/2,height/2);
	}
	for(let i = 0; i < p.length; i++){
		let ax = 0;
		let ay = 0;

		for(let j = 0; j < p.length; j++){
			if(i != j){

				let dis = dist(p[i].x,p[i].y,p[j].x,p[j].y)

				let dx = p[j].x - p[i].x;
				let dy = p[j].y - p[i].y;
				let d = sqrt(dx*dx + dy*dy);
				if(d < 1){
					d = 1;
				}

				if(dis < 100){
					stroke((frameCount/10+p[i].h)%100,20,100-p[i].h*2);
					line(p[i].x,p[i].y,p[j].x,p[j].y)
				}

				let f = (d-300) * p[j].mass /d;
				ax += f * dx;
				ay += f * dy;
			}
		}
		p[i].vx = p[i].vx * 0.97 + ax * p[i].mass;
		p[i].vy = p[i].vy * 0.97 + ay * p[i].mass;
	}

	for(let i = 0; i < p.length; i++){
		p[i].move();
		p[i].display();
		if(p[i].timer > 600){
			p.splice(i,1);
		}
	}
}

function addNewParticle() {
	p.push(new Particle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
}

class Particle{

	constructor(x,y){
		this.x = x;
		this.y = y;
		this.vx = 0;
		this.vy = 0;
		this.mass = random(0.003, 0.03)
		this.h = random(-5,5);
		this.timer = 0;
	}

	display(){
		fill((frameCount/10+this.h)%100,100,100-this.h*2,80);
		ellipse(this.x,this.y, this.mass * 1000,this.mass * 1000);
	}

	move(){
		this.x += this.vx;
		this.y += this.vy;
		this.timer++;
	}
}



function mouseClicked() {
	addNewParticle();
}



function mouseDragged() {
	addNewParticle();
}

